<?php
require_once dirname(__DIR__).'/config.php'; start_app_session();
if (empty($_SESSION['user_id'])) { http_response_code(403); exit('Please sign in to the Farming with Urunji management system first, then open this page again. <a href="../index.php?page=login">Staff login</a>'); }
$pdo=db();
$pdo->exec("CREATE TABLE IF NOT EXISTS marketplace_products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,description TEXT NULL,category ENUM('shop','crops','cattle') NOT NULL,price DECIMAL(12,2) NULL,unit VARCHAR(60) NULL,availability VARCHAR(100) NOT NULL DEFAULT 'Ask us',image_path VARCHAR(255) NULL,is_published TINYINT(1) NOT NULL DEFAULT 1,featured TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_market_category (category,is_published)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$msg=''; $allowed=['shop','crops','cattle'];
if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $action=$_POST['action']??'';
 if($action==='delete'){ $id=(int)($_POST['id']??0); $st=$pdo->prepare('DELETE FROM marketplace_products WHERE id=?');$st->execute([$id]);$msg='Product listing deleted.'; }
 elseif($action==='save'){ $id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');$cat=$_POST['category']??'shop';$price=trim($_POST['price']??'');$unit=trim($_POST['unit']??'');$availability=trim($_POST['availability']??'Ask us');$published=isset($_POST['is_published'])?1:0;$featured=isset($_POST['featured'])?1:0;$image='';
  if(isset($_FILES['image'])&&$_FILES['image']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['image'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??'';if($ext===''||$f['size']>5*1024*1024){$msg='Image must be JPG, PNG or WebP and under 5 MB.';}else{$filename='product_'.bin2hex(random_bytes(8)).'.'.$ext;$dest=__DIR__.'/uploads/'.$filename;if(move_uploaded_file($f['tmp_name'],$dest))$image='uploads/'.$filename;else $msg='Could not save the uploaded image.';}}
  if($name===''||!in_array($cat,$allowed,true)){ $msg='Please provide a product name and valid category.'; } elseif($msg===''){ $priceVal=($price!==''&&is_numeric($price)&&((float)$price)>=0)?(float)$price:null; if($id>0){if($image!==''){$st=$pdo->prepare('UPDATE marketplace_products SET name=?,description=?,category=?,price=?,unit=?,availability=?,image_path=?,is_published=?,featured=? WHERE id=?');$st->execute([$name,$desc,$cat,$priceVal,$unit,$availability,$image,$published,$featured,$id]);}else{$st=$pdo->prepare('UPDATE marketplace_products SET name=?,description=?,category=?,price=?,unit=?,availability=?,is_published=?,featured=? WHERE id=?');$st->execute([$name,$desc,$cat,$priceVal,$unit,$availability,$published,$featured,$id]);}$msg='Product listing updated.';}else{$st=$pdo->prepare('INSERT INTO marketplace_products(name,description,category,price,unit,availability,image_path,is_published,featured) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute([$name,$desc,$cat,$priceVal,$unit,$availability,$image?:null,$published,$featured]);$msg='Product listing added.';} }
 }
}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM marketplace_products WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch()?:null;}
$products=$pdo->query('SELECT * FROM marketplace_products ORDER BY created_at DESC')->fetchAll();
$pageTitle='Marketplace Product Manager | Farming with Urunji';$activePage='products';include __DIR__.'/includes/header.php';
?>
<section class="page-hero"><div class="wrap"><div class="crumbs"><a href="index.php">Home</a> / Marketplace Manager</div><span class="kicker">Staff area</span><h1>Marketplace product manager</h1><p>Add and update public website listings without editing code. This adds a separate marketplace catalogue table; existing farm records and tables are not altered.</p></div></section><section><div class="wrap admin-wrap"><p><a class="text-link" href="../index.php">← Return to management system</a></p><?php if($msg!==''):?><div class="notice"><?=h($msg)?></div><?php endif;?><div class="contact-card"><h2><?= $edit?'Edit product listing':'Add a product listing' ?></h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h($edit['id']??0)?>"><div class="form-grid"><div class="field"><label>Product name *</label><input name="name" required value="<?=h($edit['name']??'')?>"></div><div class="field"><label>Category *</label><select name="category"><option value="shop" <?=($edit['category']??'')==='shop'?'selected':''?>>Shop products</option><option value="crops" <?=($edit['category']??'')==='crops'?'selected':''?>>Onion & beans farm</option><option value="cattle" <?=($edit['category']??'')==='cattle'?'selected':''?>>Cattle products</option></select></div><div class="field"><label>Price (MWK, optional)</label><input name="price" type="number" min="0" step="0.01" value="<?=h($edit['price']??'')?>" placeholder="Leave blank for enquiry"></div><div class="field"><label>Unit / package</label><input name="unit" value="<?=h($edit['unit']??'')?>" placeholder="e.g. per kg, 50 kg bag"></div><div class="field"><label>Availability label</label><input name="availability" value="<?=h($edit['availability']??'Ask us')?>" placeholder="In stock / Seasonal / Ask us"></div><div class="field"><label>Product photo (JPG, PNG, WebP; max 5 MB)</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"></div><div class="field full"><label>Description</label><textarea name="description"><?=h($edit['description']??'')?></textarea></div><div class="field"><label><input type="checkbox" name="is_published" value="1" <?=(!isset($edit['is_published'])||(int)$edit['is_published']===1)?'checked':''?>> Publish on website</label></div><div class="field"><label><input type="checkbox" name="featured" value="1" <?=!empty($edit['featured'])?'checked':''?>> Feature this product first</label></div><div class="field full"><button class="btn" type="submit">Save product listing</button> <?php if($edit):?><a class="btn outline" href="product-admin.php">Cancel edit</a><?php endif;?></div></div></form></div><div class="contact-card" style="margin-top:25px;overflow-x:auto"><h2>Current product listings (<?=count($products)?>)</h2><?php if(!$products):?><p class="muted">No listings have been added yet. Use the form above to publish the first product.</p><?php else:?><table class="admin-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Published</th><th>Actions</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><?=h($p['name'])?></td><td><?=h(['shop'=>'Shop','crops'=>'Onion & beans','cattle'=>'Cattle'][$p['category']]??$p['category'])?></td><td><?=($p['price']!==null?'MWK '.number_format((float)$p['price'],2):'On enquiry')?></td><td><?=((int)$p['is_published']?'Yes':'No')?></td><td><div class="admin-actions"><a class="small-btn" href="?edit=<?=(int)$p['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this listing?')"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="small-btn danger" type="submit">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></div></section><?php include __DIR__.'/includes/footer.php'; ?>
